const axios = require('axios');

async function authenticateWithVault() {
  // The service proves its identity using a Kubernetes service account
  // token, not a static password baked into config.
  const jwt = require('fs').readFileSync(
    '/var/run/secrets/kubernetes.io/serviceaccount/token', 'utf8'
  );

  const res = await axios.post(`${process.env.VAULT_ADDR}/v1/auth/kubernetes/login`, {
    role: 'order-service',
    jwt
  });

  return res.data.auth.client_token; // short lived, expires soon
}

async function fetchDbCredential(vaultToken) {
  const res = await axios.get(
    `${process.env.VAULT_ADDR}/v1/database/creds/order-service-role`,
    { headers: { 'X-Vault-Token': vaultToken } }
  );

  return {
    username: res.data.data.username,
    password: res.data.data.password,
    leaseId: res.data.lease_id // needed to renew before it expires
  };
}

async function startup() {
  const vaultToken = await authenticateWithVault();
  const dbCred = await fetchDbCredential(vaultToken);

  // The password only ever exists in memory from here on. It never
  // touches a config file, an image layer, or a log line.
  const pool = createDbPool({ user: dbCred.username, password: dbCred.password });
  return pool;
}

